/**
 * UC-C4.4 — AMBIENT MEDIA INTELLIGENCE FOUNDATION (owner-directed, 2026-09-30).
 *
 * A SEPARATE suite from social-composer.js (per the brief's own report-format split:
 * "new Composer integration tests" vs "metadata unit tests") — social-composer.js's
 * accepted 140 checks are not touched by this pass at all.
 *
 * Every scenario here drives the REAL pipeline: a real uploaded JPEG file, carrying REAL
 * embedded EXIF (GPS/DateTimeOriginal/device), generated by prototype-tests/fixtures/
 * generate-exif-fixtures.cjs via piexifjs — never a fixture whose takenPlace is already
 * "Kathmandu". Reverse-geocoding is exercised through the real client → /api/geocode →
 * Nominatim path, deterministically short-circuited server-side via a `mock=1` test-only
 * query param (never a real network call in CI) that resolves a small, explicit lookup
 * table of the exact coordinates these fixtures carry.
 *
 * §1  JPEG with real EXIF GPS → recordPlace (source: metadata), deterministic geocode
 * §2  JPEG with real capture timestamp → eventTime prefilled
 * §3  Place control shows the derived Place as its default value
 * §4  User can override the suggested Place; override outranks metadata
 * §5  Original MediaAsset metadata is immutable after post + after a user override
 * §6  No EXIF at all — a normal, quiet path (no suggestion, no fake recordPlace)
 * §7  EXIF present but no GPS — time prefills, no place suggestion
 * §8  Reverse-geocode failure — no fake Place, POST still works
 * §9  Conflicting GPS across multiple assets — recordPlace unfabricated
 * §10 Consistent (geocoded) location across multiple different-GPS assets
 * §11 A user-chosen event time is never overwritten by a later-attached capture time
 * §12 Corrupted EXIF section — media stays usable, attachment does not break
 * §13 No raw GPS anywhere in the Social state/DOM
 * §14 Multi-asset independence — one bad asset does not break the others
 */
const path = require("path");
const { launch, sleep } = require("./celestial-lib");

const HOST = "http://localhost:3210";
const B = `${HOST}/style-lab/social?harness=0`;
const FIX = (name) => path.join(__dirname, "fixtures", name);
let passed = 0;
const failures = [];
const ok = (c, m) => { if (c) { passed += 1; console.log(`  ✓ ${m}`); } else { failures.push(m); console.log(`  ✗ ${m}`); } };
const DESKTOP = { width: 1440, height: 1000, deviceScaleFactor: 1 };

// UC-C4.4 test-only geocode bypass: `mockgeo=1` on the page URL makes the client's
// geocode caller add `&mock=1` to its own /api/geocode request; the server route then
// resolves a small explicit table instead of calling Nominatim. Never wired to any other
// state/store — read directly from window.location.search inside the new client module.
async function open(page, extra = "") {
  await page.setCookie({ name: "sb-locale", value: "en", url: HOST });
  await page.setViewport(DESKTOP);
  await page.goto(`${B}&theme=light&mockgeo=1${extra}`, { waitUntil: "networkidle2" });
  await sleep(900);
}
const state = (page) => page.evaluate(() => window.__SB_SOCIAL_STATE);
const openComposer = async (page) => { await page.click("[data-sb-open-composer]"); await sleep(450); };
const setText = (page, v) => page.evaluate((x) => { const ta = document.getElementById("sb-composer-text"); const set = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value").set; set.call(ta, x); ta.dispatchEvent(new Event("input", { bubbles: true })); }, v);
const post = async (page) => { await page.evaluate(() => [...document.querySelectorAll("[data-sb-composer] footer button")].find((b) => /^(Post|Save)$/.test(b.textContent.trim()) || b.getAttribute("aria-busy"))?.click()); await sleep(1300); };
const newest = async (page) => (await state(page)).moments.filter((m) => m.id.startsWith("m-new-"))[0];
const discard = async (page) => { await page.keyboard.press("Escape"); await sleep(250); await page.evaluate(() => [...document.querySelectorAll("[data-sb-composer] footer button")].find((b) => b.textContent.trim() === "Discard")?.click()); await sleep(400); };
const readPlaceChip = (page) => page.evaluate(() => [...document.querySelectorAll("[data-sb-composer-actions] button")].find((b) => b.getAttribute("aria-label") === "Place")?.textContent.trim());
const openPlaceSheet = (page) => page.evaluate(() => [...document.querySelectorAll("[data-sb-composer-actions] button")].find((b) => b.getAttribute("aria-label") === "Place")?.click());
const typePlace = (page, v) => page.evaluate((val) => { const i = document.getElementById("sb-place-common"); const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set; set.call(i, val); i.dispatchEvent(new Event("input", { bubbles: true })); }, v);

/**
 * REAL file upload: open the Media sheet (which renders the hidden real <input
 * type=file multiple> in the DOM) and drive that input DIRECTLY via Puppeteer's
 * uploadFile — never clicking the visible "Upload" row, which calls the input's own
 * .click() and would otherwise try to open a real native OS file dialog.
 */
const uploadReal = async (page, absPaths) => {
  await page.evaluate(() => [...document.querySelectorAll("[data-sb-composer-actions] button")].find((b) => b.getAttribute("aria-label") === "Media")?.click());
  await sleep(300);
  const input = await page.waitForSelector("input[type=file][multiple]");
  await input.uploadFile(...absPaths);
  await sleep(3800); // real EXIF parse + a real (mocked) network round-trip to /api/geocode, per asset
};

(async () => {
  const { browser, page } = await launch();
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e)));
  try {
    /* ================= §1/§3 REAL GPS → recordPlace + Social default, no confirmation ================= */
    console.log("§1/§3 real EXIF GPS → deterministic reverse-geocode → recordPlace + Social default");
    await open(page);
    await openComposer(page);
    await uploadReal(page, [FIX("exif-gps-kathmandu.jpg")]);
    const chip1 = await readPlaceChip(page);
    await setText(page, "UC-C4.4 §1 — real GPS EXIF, default use");
    await post(page);
    const m1 = await newest(page);
    ok(chip1 === "Kathmandu, Nepal" && m1?.recordPlace?.value === "Kathmandu, Nepal" && m1.recordPlace?.source === "metadata" && m1.place === "Kathmandu, Nepal",
      "1/3. a real photo's embedded GPS is extracted, reverse-geocoded, and becomes recordPlace + the Social default — the Place chip already showed it before any click");

    /* ================= §2 REAL CAPTURE TIME ================= */
    console.log("§2 real EXIF capture timestamp → eventTime prefilled");
    await openComposer(page);
    await uploadReal(page, [FIX("exif-gps-kathmandu.jpg")]);
    await setText(page, "UC-C4.4 §2 — real capture time");
    await post(page);
    const m2 = await newest(page);
    // The EXISTING, accepted, frozen §21 rule (unchanged by this pass): a `takenAt`-derived
    // date is "day" precision with a noon SORT ANCHOR — the exact clock time is never
    // preserved for ANY source, fixture or real EXIF alike. What's new here is that the
    // DATE itself (2026-09-29) came from a real photo's own DateTimeOriginal, not a fixture.
    ok(m2?.at === "2026-09-29T12:00:00" && m2.atPrecision === "day",
      `2. the photo's own real DateTimeOriginal date prefills the event date (day precision, noon anchor — got "${m2?.at}")`);

    /* ================= §4 USER OVERRIDE ================= */
    console.log("§4 user Place override outranks metadata");
    await openComposer(page);
    await uploadReal(page, [FIX("exif-gps-kathmandu.jpg")]);
    await openPlaceSheet(page);
    await sleep(300);
    await typePlace(page, "Lalitpur, Nepal");
    await page.click("[data-sb-place-done]");
    await sleep(200);
    await setText(page, "UC-C4.4 §4 — user overrides the metadata place");
    await post(page);
    const m4 = await newest(page);
    ok(m4?.recordPlace?.value === "Lalitpur, Nepal" && m4.recordPlace?.source === "user" && m4.place === "Lalitpur, Nepal",
      "4. the user's own Place replaces the metadata suggestion; recordPlace.source becomes 'user'");

    /* ================= §5 ORIGINAL MEDIA METADATA IMMUTABILITY ================= */
    console.log("§5 original media metadata is immutable (real deep-clone/compare)");
    await openComposer(page);
    const before5 = await page.evaluate(() => window.__SB_ASSET_SNAPSHOT?.());
    await uploadReal(page, [FIX("exif-gps-kathmandu.jpg")]);
    await openPlaceSheet(page);
    await sleep(300);
    await typePlace(page, "Somewhere Else Entirely");
    await page.click("[data-sb-place-done]");
    await sleep(200);
    await setText(page, "UC-C4.4 §5 — immutability after a user override");
    await post(page);
    await openComposer(page);
    const after5 = await page.evaluate(() => window.__SB_ASSET_SNAPSHOT?.());
    await page.evaluate(() => document.querySelector("[data-sb-composer] header button")?.click());
    await sleep(300);
    const upload5 = (before5 ?? []).length !== (after5 ?? []).length ? null : (after5 ?? []).find((a) => !(before5 ?? []).some((b) => JSON.stringify(b) === JSON.stringify(a)));
    ok(!!before5 && !!after5 && (after5 ?? []).some((a) => a.sourceMetadata?.normalized?.gps?.latitude === 27.658875) &&
       JSON.stringify(before5.filter((a) => !a.id.startsWith("up-"))) === JSON.stringify(after5.filter((a) => !a.id.startsWith("up-"))),
      "5. every LIBRARY asset stays byte-for-byte identical, and the just-uploaded asset's OWN sourceMetadata GPS is still the real original 27.658875 — unchanged by the user's Place override or the submission");

    /* ================= §6 NO EXIF AT ALL ================= */
    console.log("§6 no EXIF at all — a normal, quiet path");
    await openComposer(page);
    await uploadReal(page, [FIX("no-exif.jpg")]);
    const noBanner6 = await page.evaluate(() => !document.querySelector("[data-sb-metadata-review]"));
    const chip6 = await readPlaceChip(page);
    await setText(page, "UC-C4.4 §6 — no EXIF at all");
    await post(page);
    const m6 = await newest(page);
    ok(noBanner6 && chip6 === "Place" && m6?.recordPlace === undefined && !m6?.place,
      "6. a JPEG with no EXIF at all produces no suggestion, no fake recordPlace, and POST still works");

    /* ================= §7 EXIF PRESENT, NO GPS ================= */
    console.log("§7 EXIF present but no GPS — time prefills, no place suggestion");
    await openComposer(page);
    await uploadReal(page, [FIX("exif-time-only.jpg")]);
    const chip7 = await readPlaceChip(page);
    await setText(page, "UC-C4.4 §7 — EXIF time only, no GPS");
    await post(page);
    const m7 = await newest(page);
    ok(chip7 === "Place" && m7?.recordPlace === undefined && !m7?.place && m7?.at === "2026-09-20T12:00:00" && m7.atPrecision === "day",
      "7. EXIF with a real capture time but no GPS prefills only the date (day precision), never a fabricated place");

    /* ================= §8 REVERSE-GEOCODE FAILURE ================= */
    console.log("§8 reverse-geocode failure — no fake Place, POST still works");
    await openComposer(page);
    await uploadReal(page, [FIX("exif-gps-unknown.jpg")]);
    const chip8 = await readPlaceChip(page);
    const postGate8 = await page.evaluate(() => [...document.querySelectorAll("[data-sb-composer] footer button")].find((b) => b.textContent.trim() === "Post")?.getAttribute("aria-disabled"));
    await setText(page, "UC-C4.4 §8 — geocode lookup found nothing");
    await post(page);
    const m8 = await newest(page);
    ok(chip8 === "Place" && postGate8 !== "true" && m8?.recordPlace === undefined && !m8?.place,
      "8. real GPS that the geocoder cannot resolve leaves recordPlace undefined — never an error, never a blocked POST");

    /* ================= §9 CONFLICTING GPS ACROSS MULTIPLE ASSETS ================= */
    console.log("§9 conflicting GPS across two real assets — no fabricated winner");
    await openComposer(page);
    await uploadReal(page, [FIX("exif-gps-kathmandu.jpg"), FIX("exif-gps-pokhara.jpg")]);
    const chip9 = await readPlaceChip(page);
    await setText(page, "UC-C4.4 §9 — two real, materially different GPS locations");
    await post(page);
    const m9 = await newest(page);
    ok(chip9 === "Place" && m9?.recordPlace === undefined && !m9?.place,
      "9. two really-different GPS locations across attached assets leave recordPlace unfabricated (never the first asset, never the last)");

    /* ================= §10 CONSISTENT (GEOCODED) LOCATION ACROSS MULTIPLE ASSETS ================= */
    console.log("§10 two different real GPS points that geocode to the same place — accepted");
    await openComposer(page);
    await uploadReal(page, [FIX("exif-gps-kathmandu.jpg"), FIX("exif-gps-kathmandu-2.jpg")]);
    const chip10 = await readPlaceChip(page);
    await setText(page, "UC-C4.4 §10 — two different GPS points, same geocoded city");
    await post(page);
    const m10 = await newest(page);
    ok(chip10 === "Kathmandu, Nepal" && m10?.recordPlace?.value === "Kathmandu, Nepal" && m10.recordPlace?.source === "metadata",
      "10. two assets with different raw GPS that resolve to the SAME human-readable place are accepted — consistency is judged on the derived place, not the raw coordinates");

    /* ================= §11 USER TIME NEVER OVERWRITTEN ================= */
    console.log("§11 a user-chosen event time is never overwritten by a later capture time");
    await openComposer(page);
    await page.evaluate(() => [...document.querySelectorAll("[data-sb-composer-actions] button")].find((b) => b.getAttribute("aria-label") === "Add details")?.click());
    await sleep(300);
    await page.evaluate(() => [...document.querySelectorAll("[data-sb-kind-row] button")].find((b) => b.getAttribute("aria-label") === "Life Moment")?.click());
    await sleep(300);
    await page.evaluate(() => { const b = document.querySelector("[data-sb-more-toggle]"); if (b && b.getAttribute("aria-expanded") !== "true") b.click(); });
    await sleep(300);
    await page.evaluate(() => document.querySelector("[data-sb-when-change]")?.click());
    await sleep(250);
    await page.evaluate(() => { const i = document.querySelector("[data-sb-when] input[type=date]"); const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set; set.call(i, "2019-05-04"); i.dispatchEvent(new Event("input", { bubbles: true })); i.dispatchEvent(new Event("change", { bubbles: true })); });
    await sleep(250);
    await uploadReal(page, [FIX("exif-gps-kathmandu.jpg")]);
    await setText(page, "UC-C4.4 §11 — the person's own date survives a later real capture time");
    await post(page);
    const m11 = await newest(page);
    ok(m11?.at === "2019-05-04T12:00:00" && m11.atPrecision === "day",
      "11. the person's own chosen date is never overwritten by a photo's real capture time attached afterwards");

    /* ================= §12 CORRUPTED EXIF, VALID MEDIA ================= */
    console.log("§12 corrupted EXIF section — the media itself stays usable");
    await openComposer(page);
    await uploadReal(page, [FIX("corrupt-exif.jpg")]);
    const thumb12 = await page.evaluate(() => document.querySelectorAll("[data-sb-media-collage] [data-sb-thumb]").length);
    const chip12 = await readPlaceChip(page);
    await setText(page, "UC-C4.4 §12 — corrupted metadata, valid photo");
    await post(page);
    const m12 = await newest(page);
    ok(thumb12 === 1 && chip12 === "Place" && m12?.media?.kind === "photos" && m12.recordPlace === undefined,
      "12. a JPEG with a corrupted/truncated EXIF section still attaches and posts normally — metadata parsing failure never breaks attachment");

    /* ================= §13 NO RAW GPS ANYWHERE SOCIALLY ================= */
    console.log("§13 no raw GPS coordinates anywhere in Social state or the rendered DOM");
    const stateJson = JSON.stringify(await state(page));
    const domText = await page.evaluate(() => document.body.innerText);
    ok(!/27\.65887|85\.29344|28\.20996|83\.95883/.test(stateJson) && !/27\.65887|85\.29344/.test(domText),
      "13. raw latitude/longitude never appears in the Social store state or the rendered page — only human-readable place names");

    /* ================= §14 MULTI-ASSET INDEPENDENCE ================= */
    console.log("§14 one bad asset never breaks the others in the same attach");
    await openComposer(page);
    await uploadReal(page, [FIX("corrupt-exif.jpg"), FIX("exif-gps-kathmandu.jpg")]);
    const thumbs14 = await page.evaluate(() => document.querySelectorAll("[data-sb-media-collage] [data-sb-thumb]").length);
    const chip14 = await readPlaceChip(page);
    await setText(page, "UC-C4.4 §14 — a bad asset alongside a good one");
    await post(page);
    const m14 = await newest(page);
    // two PHOTOS (no video) is the existing, unchanged "photos" media kind — never "gallery"
    // (that's reserved for a mix of photos+video or multiple videos, per buildMedia).
    ok(thumbs14 === 2 && chip14 === "Kathmandu, Nepal" && m14?.recordPlace?.value === "Kathmandu, Nepal" && m14.media?.kind === "photos" && m14.media?.items?.length === 2,
      "14. a corrupted-metadata asset attached alongside a good one never blocks the good asset's own real metadata from working");

    console.log("page health");
    ok(errs.length === 0, `zero page errors (${errs.length})${errs[0] ? " — " + errs[0].slice(0, 140) : ""}`);
  } finally {
    await browser.close();
  }
  console.log(`\nmedia-intelligence: ${passed} passed, ${failures.length} failed`);
  if (failures.length) { failures.forEach((f) => console.log("  FAILED: " + f)); process.exit(1); }
  process.exit(0);
})();
